TEMPLATE = 'import numpy as np\nfrom collections import deque\n\nBG = __BG__\nFG = __FG__\n\n\ndef _boxes(g):\n    h, w = g.shape\n    seen = np.zeros((h, w), dtype=bool)\n    boxes = []\n    for y in range(h):\n        for x in range(w):\n            if g[y, x] != BG and not seen[y, x]:\n                seen[y, x] = True\n                q = deque([(y, x)])\n                y0, x0, y1, x1 = y, x, y, x\n                while q:\n                    cy, cx = q.popleft()\n                    y0 = min(y0, cy)\n                    y1 = max(y1, cy)\n                    x0 = min(x0, cx)\n                    x1 = max(x1, cx)\n                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):\n                        ny, nx = cy + dy, cx + dx\n                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] != BG:\n                            seen[ny, nx] = True\n                            q.append((ny, nx))\n                boxes.append((y0, x0, y1, x1))\n    return boxes\n\n\ndef _nested(a0, a1, b0, b1):\n    return (a0 >= b0 and a1 <= b1) or (b0 >= a0 and b1 <= a1)\n\n\ndef _unique_spanning_tree(n, edges):\n  """True iff the minimum spanning tree over edges (w, i, j) exists and is unique."""\n  parent = list(range(n))\n  def find(x):\n    while parent[x] != x:\n      parent[x] = parent[parent[x]]\n      x = parent[x]\n    return x\n  tree = [[] for _ in range(n)]\n  rest, count = [], 0\n  for w, i, j in sorted(edges):\n    ri, rj = find(i), find(j)\n    if ri == rj:\n      rest.append((w, i, j))\n      continue\n    parent[ri] = rj\n    tree[i].append((j, w))\n    tree[j].append((i, w))\n    count += 1\n  if count != n - 1: return False\n  for w, i, j in rest:\n    best, stack = {i: 0}, [i]\n    while stack:\n      u = stack.pop()\n      for v, wv in tree[u]:\n        if v not in best:\n          best[v] = max(best[u], wv)\n          stack.append(v)\n    if best[j] >= w: return False  # An equal-weight swap gives another tree.\n  return True\n\n\n\ndef solve(demonstrations, grid):\n    g = np.array(grid, dtype=int)\n    out = g.copy()\n    boxes = sorted(_boxes(g))\n    n = len(boxes)\n    cands = []\n    for i in range(n):\n        for j in range(i + 1, n):\n            A, B = boxes[i], boxes[j]\n            # side by side: row span nested, pipe runs along the two interior rows a, b\n            if (A[3] < B[1] or B[3] < A[1]) and _nested(A[0], A[2], B[0], B[2]):\n                L, R = (A, B) if A[3] < B[1] else (B, A)\n                a = max(L[0], R[0]) + 1\n                b = min(L[2], R[2]) - 1\n                s0, s1 = L[3] + 1, R[1] - 1\n                if b >= a and s1 >= s0 and np.all(g[a, s0:s1 + 1] == BG) and np.all(g[b, s0:s1 + 1] == BG):\n                    cands.append((s1 - s0 + 1, 0, L, R, i, j, a, b))\n            # stacked: column span nested, pipe runs along the two interior columns a, b\n            if (A[2] < B[0] or B[2] < A[0]) and _nested(A[1], A[3], B[1], B[3]):\n                T, D = (A, B) if A[2] < B[0] else (B, A)\n                a = max(T[1], D[1]) + 1\n                b = min(T[3], D[3]) - 1\n                s0, s1 = T[2] + 1, D[0] - 1\n                if b >= a and s1 >= s0 and np.all(g[s0:s1 + 1, a] == BG) and np.all(g[s0:s1 + 1, b] == BG):\n                    cands.append((s1 - s0 + 1, 1, T, D, i, j, a, b))\n    if not _unique_spanning_tree(n, [(gap, i, j) for gap, axis, P, Q, i, j, a, b in cands]):\n        raise ValueError("Pipe graph has no unique minimum spanning tree")\n    cands.sort()\n    parent = list(range(n))\n\n    def find(x):\n        while parent[x] != x:\n            parent[x] = parent[parent[x]]\n            x = parent[x]\n        return x\n\n    for gap, axis, P, Q, i, j, a, b in cands:\n        ri, rj = find(i), find(j)\n        if ri == rj:\n            continue\n        parent[ri] = rj\n        if axis == 0:\n            out[a, P[3] + 1:Q[1]] = FG\n            out[b, P[3] + 1:Q[1]] = FG\n            if b - a >= 2:\n                out[a + 1:b, P[3]] = BG\n                out[a + 1:b, Q[1]] = BG\n        else:\n            out[P[2] + 1:Q[0], a] = FG\n            out[P[2] + 1:Q[0], b] = FG\n            if b - a >= 2:\n                out[P[2], a + 1:b] = BG\n                out[Q[0], a + 1:b] = BG\n    return out.tolist()\n'

def build_program(d4, palette):
    return TEMPLATE.replace("__BG__", str(int(palette[0]))).replace("__FG__", str(int(palette[3])))
